import { esc, icon, button, money, sourceLink } from './common.js';
import { summarize } from '../game/engine.js';
export function resultsView(topic,run) {
  const s=summarize(topic,run);
  const tied=s.categories.every(c=>c.accuracy===s.categories[0].accuracy);
  return `<main id="main" class="results-page page-enter"><div class="results-heading"><span class="eyebrow">${icon('check')} BOARD COMPLETE · TOPIC ${topic.topic}</span><h1 id="page-title" tabindex="-1">A little more <em>connected.</em></h1><p>${esc(topic.title)} · Here’s what to carry into your next review.</p></div>
    <div class="result-stats"><div class="primary-stat"><span class="eyebrow">FINAL SCORE</span><strong>${money(s.score)}</strong><small>of $7,500 possible</small></div><div><span class="eyebrow">ACCURACY</span><strong>${s.accuracy}<span>%</span></strong><small>Across all 25 questions</small></div><div><span class="eyebrow">CORRECT</span><strong>${s.correct}</strong><small>Connections recalled</small></div><div><span class="eyebrow">INCORRECT</span><strong>${s.incorrect}</strong><small>${s.incorrect?'Ready to revisit':'Nothing to revisit this time'}</small></div></div>
    <div class="results-actions">${button(icon('book')+` Review missed questions${s.incorrect?' ('+s.incorrect+')':''}`,'review','button primary',s.incorrect?'':'disabled')}${button(icon('reset')+' Play again','replay','button secondary')}${button('Back to topics '+icon('arrow'),'home','button secondary')}</div>
    <section class="category-recap" aria-labelledby="category-title"><div><span class="eyebrow muted">YOUR STUDY SNAPSHOT</span><h2 id="category-title">The ideas behind the score.</h2><p>Use this to decide what deserves another look.</p><div class="strength"><span class="eyebrow">STRONGEST ${s.strongest.length>1?'· TIED':''}</span><strong>${esc(s.strongest.join(' · '))}</strong></div><div class="strength review-strength"><span class="eyebrow">WEAKEST ${s.weakest.length>1?'· TIED':''}</span><strong>${esc(s.weakest.join(' · '))}</strong>${tied?'<small>All categories are level this time.</small>':''}</div></div><div class="category-bars">${s.categories.map(c=>`<div class="category-row"><div><strong>${esc(c.name)}</strong><span>${c.correct}/5 <b>${c.accuracy}%</b></span></div><div class="accuracy-track"><span style="width:${c.accuracy}%"></span></div></div>`).join('')}</div></section>
    <section class="missed-section" aria-labelledby="missed-title"><div class="section-heading"><div><span class="eyebrow muted">KEEP THE LEARNING GOING</span><h2 id="missed-title">${s.missed.length?'Worth another look.':'Everything recalled.'}</h2></div><span>${s.missed.length} missed questions</span></div>${s.missed.length?`<p class="missed-intro">Every missed question, with the key idea and the reason behind it.</p><div class="missed-list">${s.missed.map(q=>`<article class="missed-card"><div class="eyebrow">${esc(q.category)} <span>${money(q.value)}</span></div><h3>${esc(q.prompt)}</h3><strong class="missed-answer">${esc(q.answer)}</strong><p>${esc(q.explanation)}</p>${sourceLink(q)}</article>`).join('')}</div>`:'<p class="empty-review">There’s nothing in your review list. Return to a board whenever you want to test what stays with you.</p>'}</section>
    <div class="recap-bottom">${button(icon('undo')+' Correct the last grading decision','undo','text-button')}<span>Progress saved on this device when storage is available.</span></div></main>`;
}
